# -*- coding: utf-8 -*-
"""Embedded complete Airbnb photo set for corrected lot 1220 publication."""
import base64
import io
import shutil
import zipfile
from pathlib import Path

ZIP_B64 = """







"""
PHOTO_NAMES = [f"full_{i:02d}.jpeg" for i in range(1, 8)]

def materialize() -> list[Path]:
    work = Path("/tmp/cozy_airbnb_sgphb3_1220")
    if work.exists():
        shutil.rmtree(work)
    work.mkdir(parents=True)
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(ZIP_B64)), "r") as zf:
        zf.extractall(work)
    photos = [work / name for name in PHOTO_NAMES]
    if any(not p.is_file() for p in photos):
        raise RuntimeError("Embedded complete Airbnb photo set is incomplete")
    return photos
